<template>
  <section class="hero-list">
    <div class="toolbar">
      <el-input v-model="keyword" clearable placeholder="搜索武将名 / 战法" class="search-input"><template #prefix>⌕</template></el-input>
      <div class="filter-row"><span class="filter-label">阵营</span><el-radio-group v-model="countryFilter" size="small"><el-radio-button label="全部" /><el-radio-button v-for="country in countries" :key="country" :label="country" /></el-radio-group></div>
      <div class="filter-row"><span class="filter-label">战法</span><el-radio-group v-model="typeFilter" size="small"><el-radio-button label="全部" /><el-radio-button v-for="type in tacticTypes" :key="type" :label="type" /></el-radio-group></div>
      <div class="filter-row"><span class="filter-label">排序</span><el-radio-group v-model="sortKey" size="small"><el-radio-button label="name">武将名</el-radio-button><el-radio-button label="attGrow">攻击成长</el-radio-button><el-radio-button label="ruseGrow">谋略成长</el-radio-button><el-radio-button label="defGrow">防御成长</el-radio-button><el-radio-button label="speedGrow">速度成长</el-radio-button><el-radio-button label="siegeGrow">攻城成长</el-radio-button></el-radio-group></div>
    </div>
    <div class="list-summary">共 {{ filteredHeroes.length }} 名武将<span v-if="filteredHeroes.length !== heroes.length">（已筛选）</span></div>
    <div v-if="pagedHeroes.length" class="hero-items">
      <article v-for="hero in pagedHeroes" :key="hero.id" class="hero-item" role="button" tabindex="0" @click="openHero(hero)" @keydown.enter="openHero(hero)">
        <CardItem :name="hero.name" :image-url="hero.imageUrl" :country="hero.countryId" :quality="hero.qualityId" :season="hero.season" :hero-id="hero.id" :advance-num="0" :awake-state="0" />
        <div class="hero-info"><div class="hero-title"><strong :class="`level-${hero.level}`">{{ hero.name }}</strong><el-tag size="small" :type="typeTagType(hero.type)">{{ hero.type }}</el-tag><span v-if="hero.mp !== undefined && hero.mp !== null && hero.mp !== ''" class="probability">概率 {{ hero.mp }}%</span><span class="cost">{{ hero.cost }}C</span></div><p class="tactic"><b>{{ hero.methodName || '暂无战法' }}</b>：{{ hero.methodDesc || '暂无描述' }}</p><div class="stats"><span :class="{ 'stat-highlight': maxGrowth(hero) === Number(hero.attGrow) }" title="初始攻击 / 攻击成长">攻 {{ hero.attack }} <i>+{{ hero.attGrow }}</i></span><span :class="{ 'stat-highlight': maxGrowth(hero) === Number(hero.ruseGrow) }" title="初始谋略 / 谋略成长">谋 {{ hero.ruse }} <i>+{{ hero.ruseGrow }}</i></span><span :class="{ 'stat-highlight': maxGrowth(hero) === Number(hero.defGrow) }" title="初始防御 / 防御成长">防 {{ hero.def }} <i>+{{ hero.defGrow }}</i></span><span :class="{ 'stat-highlight': maxGrowth(hero) === Number(hero.speedGrow) }" title="初始速度 / 速度成长">速 {{ hero.speed }} <i>+{{ hero.speedGrow }}</i></span><span :class="{ 'stat-highlight': maxGrowth(hero) === Number(hero.siegeGrow) }" title="初始攻城值 / 攻城值成长">城 {{ hero.siege }} <i>+{{ hero.siegeGrow }}</i></span></div><div class="meta">攻击距离 {{ hero.distance }}　可用兵种：{{ hero.typeAvailable || '暂无' }}</div></div>
      </article>
    </div><el-empty v-else description="没有符合条件的武将" />
    <div v-if="filteredHeroes.length" class="pagination-wrap"><el-pagination v-model:current-page="currentPage" v-model:page-size="pageSize" background layout="prev, pager, next" :page-sizes="[20, 40, 80]" :total="filteredHeroes.length" @size-change="currentPage = 1" /></div>
    <el-dialog v-model="detailVisible" :title="selectedHero ? `${selectedHero.name} - 武将详情` : '武将详情'" width="min(720px, 94vw)">
      <div v-if="selectedHero" class="hero-detail">
        <div class="detail-header"><img :src="selectedHero.imageUrl" :alt="selectedHero.name" /><div><h2 :class="`level-${selectedHero.level}`">{{ selectedHero.name }}</h2><div class="detail-stars">★★★★★</div><p>{{ selectedHero.share_desc || '暂无武将描述' }}</p></div></div>
        <div class="detail-tags"><el-tag effect="dark">cost {{ selectedHero.cost }}</el-tag><el-tag effect="dark" type="danger">战法 {{ selectedHero.type }}</el-tag><el-tag effect="dark" type="warning">阵营 {{ selectedHero.country }}</el-tag><el-tag v-if="selectedHero.mp" effect="dark" type="success">概率 {{ selectedHero.mp }}%</el-tag></div>
<div class="radar-panel"><div class="radar-legend"><span class="legend-dot inner-dot"></span>初始属性 <span class="legend-dot outer-dot"></span>40级属性 <span class="allocation">最高成长属性 +{{ selectedHero.sex === '女' ? 60 : 40 }}</span></div><svg class="radar-chart" viewBox="0 0 360 280" role="img" :aria-label="`${selectedHero.name}五维属性雷达图`"><polygon v-for="level in 4" :key="level" :points="radarGrid(level)" class="radar-grid" /><line v-for="(axis, index) in radarAxes" :key="axis.label" x1="180" y1="140" :x2="axisPoint(index, 1).x" :y2="axisPoint(index, 1).y" class="radar-axis" /><polygon :points="radarPoints(selectedHero, false)" class="radar-area initial-area" /><polygon :points="radarPoints(selectedHero, true)" class="radar-area level-area" /><text v-for="(axis, index) in radarAxes" :key="`${axis.label}-text`" :x="axisLabel(index).x" :y="axisLabel(index).y" class="radar-label" text-anchor="middle">{{ axis.label }} {{ radarValue(selectedHero, axis, false) }} <tspan class="growth-label">+{{ selectedHero[axis.grow] || '0' }}</tspan><tspan :x="axisLabel(index).x" dy="14">{{ radarValue(selectedHero, axis, true) }}</tspan></text></svg></div>
<div class="skill-detail"><h3>基础战法：{{ selectedHero.methodName || '暂无' }}</h3><p>{{ selectedHero.methodDesc || '暂无描述' }}</p><h3 v-if="selectedHero.methodName1">可拆战法：{{ selectedHero.methodName1 }}</h3><p v-if="selectedHero.methodDesc1">{{ selectedHero.methodDesc1 }}</p></div>
        <div class="detail-meta">攻击距离：{{ selectedHero.distance || '—' }}　可用兵种：{{ selectedHero.typeAvailable || '暂无' }}</div>
      </div>
    </el-dialog>
  </section>
</template>

<script setup>
import { computed, ref, watch } from 'vue'
import CardItem from '~/components/CardItem.vue'
import heroData from '~/data/heroextra.json'
const countryIds = { 汉: 1, 魏: 2, 蜀: 3, 吴: 4, 群: 5 }
const countries = ['汉', '魏', '蜀', '吴', '群']; const tacticTypes = ['主动', '指挥', '被动', '追击']
const keyword = ref(''); const countryFilter = ref('全部'); const typeFilter = ref('全部'); const sortKey = ref('attGrow'); const currentPage = ref(1); const pageSize = ref(20); const detailVisible = ref(false); const selectedHero = ref(null)
const detailStats = [{ label: '攻击', base: 'attack', grow: 'attGrow' }, { label: '谋略', base: 'ruse', grow: 'ruseGrow' }, { label: '防御', base: 'def', grow: 'defGrow' }, { label: '速度', base: 'speed', grow: 'speedGrow' }, { label: '攻城', base: 'siege', grow: 'siegeGrow' }]
const radarAxes = detailStats
const radarCenter = { x: 180, y: 140 }; const radarRadius = 88
const radarAngle = index => -Math.PI / 2 + (Math.PI * 2 * index) / radarAxes.length
const statNumber = (hero, stat, level40) => { const base = Number(hero[stat.base]) || 0; const grow = Number(hero[stat.grow]) || 0; const bonus = level40 && grow === maxGrowth(hero) ? (hero.sex === '女' ? 60 : 40) : 0; return level40 ? base + grow * 39 + bonus : base }
const radarScale = hero => Math.max(...radarAxes.map(stat => statNumber(hero, stat, true)), 1)
const axisPoint = (index, ratio) => { const angle = radarAngle(index); return { x: radarCenter.x + Math.cos(angle) * radarRadius * ratio, y: radarCenter.y + Math.sin(angle) * radarRadius * ratio } }
const radarGrid = level => radarAxes.map((_, index) => { const point = axisPoint(index, level / 4); return `${point.x},${point.y}` }).join(' ')
const radarPoints = (hero, level40) => radarAxes.map((stat, index) => { const point = axisPoint(index, statNumber(hero, stat, level40) / radarScale(hero, index)); return `${point.x},${point.y}` }).join(' ')
const radarValue = (hero, stat, level40) => statNumber(hero, stat, level40).toFixed(2)
const axisLabel = index => axisPoint(index, 1.2)
const heroes = computed(() => heroData.map(hero => ({ ...hero, countryId: countryIds[hero.country] || 5, qualityId: Number.parseInt(hero.quality, 10) || 4, season: 'N', imageUrl: `https://cbg-stzb.res.netease.com/game_res/cards/cut/card_medium_${hero.iconId || hero.id}.jpg`, typeAvailable: hero.type_availible })))
const filteredHeroes = computed(() => { const query = keyword.value.trim().toLowerCase(); return heroes.value.filter(hero => countryFilter.value === '全部' || hero.country === countryFilter.value).filter(hero => typeFilter.value === '全部' || hero.type === typeFilter.value).filter(hero => !query || [hero.name, hero.methodName, hero.methodDesc, hero.methodDesc1].some(value => String(value || '').toLowerCase().includes(query))).sort((a, b) => sortKey.value === 'name' ? a.name.localeCompare(b.name, 'zh-CN') || a.id - b.id : Number(b[sortKey.value] || 0) - Number(a[sortKey.value] || 0)) })
const pagedHeroes = computed(() => filteredHeroes.value.slice((currentPage.value - 1) * pageSize.value, currentPage.value * pageSize.value))
watch([keyword, countryFilter, typeFilter, sortKey], () => { currentPage.value = 1 })
const maxGrowth = hero => Math.max(...[hero.attGrow, hero.ruseGrow, hero.defGrow, hero.speedGrow, hero.siegeGrow].map(value => Number(value) || 0))
const openHero = hero => { selectedHero.value = hero; detailVisible.value = true }
const typeTagType = type => ({ 主动: 'danger', 指挥: 'warning', 被动: 'success', 追击: 'info' }[type] || 'info')
</script>

<style scoped>
.hero-list{width:100%;box-sizing:border-box;padding:16px;margin:0 auto}.toolbar{padding:16px;background:#fff;border-radius:10px;box-shadow:0 1px 5px #dfe3e8}.search-input{max-width:420px;margin-bottom:14px}.filter-row{display:flex;align-items:center;gap:12px;margin-top:10px;flex-wrap:wrap}.filter-label{width:32px;color:#606266;font-size:14px}.list-summary{padding:14px 4px 8px;color:#606266;font-size:14px}.hero-items{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.hero-item{display:flex;gap:14px;padding:10px 12px;background:#fff;border-radius:10px;box-shadow:0 1px 5px #e1e4e8;min-width:0;cursor:pointer}.hero-item:focus-visible{outline:2px solid #409eff}.hero-info{flex:1;min-width:0}.hero-title{display:flex;align-items:center;gap:7px;color:#303133}.hero-title strong{font-size:15px}.hero-title strong.level-S{color:#8a2c8f}.hero-title strong.level-A{color:#409eff}.hero-title strong.level-B{color:#67c23a}.hero-title strong.level-C,.hero-title strong.level-D{color:#909399}.probability{color:#d46b08;font-size:13px}.cost{color:#a86b18;font-size:13px}.tactic{margin:8px 0;color:#606266;font-size:13px;line-height:1.55;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.tactic b{color:#303133}.stats{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:6px}.stats span{padding:5px 7px;border-radius:5px;background:#f4f6f8;color:#555;text-align:center;font-size:12px}.stats span.stat-highlight{background:#fffaf0}.stats i{display:block;color:#b36b2c;font-style:normal;margin-top:2px}.meta{margin-top:7px;color:#909399;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.pagination-wrap{display:flex;justify-content:center;padding:20px 0}.detail-header{display:flex;gap:16px;align-items:center}.detail-header img{width:76px;height:110px;object-fit:cover;border-radius:6px}.detail-header h2{margin:0 0 6px;font-size:22px}.detail-header h2.level-S{color:#8a2c8f}.detail-header h2.level-A{color:#409eff}.detail-header h2.level-B{color:#67c23a}.detail-header h2.level-C,.detail-header h2.level-D{color:#909399}.detail-header p{margin:8px 0 0;color:#606266}.detail-stars{color:#d65bb0;letter-spacing:2px}.detail-tags{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}.radar-panel{padding:10px;border:1px solid #ebeef5;border-radius:8px;background:#fcfdff}.radar-legend{display:flex;justify-content:center;align-items:center;gap:7px;color:#667085;font-size:13px}.legend-dot{width:10px;height:10px;border-radius:50%;display:inline-block}.inner-dot{background:#c75a9e}.outer-dot{background:#2f80ed;margin-left:10px}.allocation{margin-left:12px;color:#a66b00}.radar-chart{display:block;width:100%;max-height:300px;margin:0 auto}.radar-grid{fill:none;stroke:#dfe3e8;stroke-width:1}.radar-axis{stroke:#dfe3e8;stroke-width:1}.radar-area{stroke-width:2}.initial-area{fill:#c75a9e33;stroke:#c75a9e}.level-area{fill:#2f80ed33;stroke:#2f80ed}.radar-label{fill:#52606d;font-size:11px}.radar-label tspan{fill:#52606d;font-size:10px}.radar-label tspan.growth-label{fill:#d64545;font-size:10px}.detail-stats{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;padding:14px;border:1px solid #ebeef5;border-radius:8px}.detail-stats div{text-align:center}.detail-stats span,.detail-stats i{display:block;margin-top:5px}.detail-stats i{color:#b36b2c;font-style:normal}.skill-detail{margin-top:18px;color:#606266;line-height:1.6}.skill-detail h3{margin:12px 0 4px;color:#303133;font-size:15px}.skill-detail p{margin:0}.detail-meta{margin-top:14px;color:#909399;font-size:13px}@media(max-width:576px){.hero-list{padding:10px 6px}.hero-items{grid-template-columns:1fr}.hero-item{gap:6px;padding:8px 5px}.stats{grid-template-columns:repeat(2,1fr)}.hero-title{flex-wrap:wrap}.filter-label{width:100%}.detail-stats{grid-template-columns:repeat(3,1fr)}}
</style>
